def transform(grid):
    h, w = len(grid), len(grid[0])
    sources = set()
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color and all(grid[y][x] == color for y in range(r, r + 3) for x in range(c, c + 3)):
                sources.add((r + 1, c + 1, color))

    rays = {}
    for r, c, color in sources:
        for x in range(w):
            rays.setdefault((r, x), set()).add(color)
        for y in range(h):
            rays.setdefault((y, c), set()).add(color)

    out = [row[:] for row in grid]
    for (r, c), colors in rays.items():
        out[r][c] = next(iter(colors)) if len(colors) == 1 else 0
    return out
